def _parse_key_value_file(path: str) -> dict[str, str]:
    if not path or not Path(path).is_file():
        return {}
    data: dict[str, str] = {}
    for line in _read_kv_file_text(Path(path)).splitlines():
        if not line or line.startswith("#") or "=" not in line:
